<script setup lang="ts">
import {ref,watch} from 'vue';import {api} from '../api';import {useUI,useData} from '../store';import {date} from '../domain';import type {Alias} from '../types';
interface DeletePreview {account_id:string;display_name:string|null;report_count:number;snapshot_rows:number;device_count:number;has_alias:boolean;hidden:boolean;delete_token:string;expires_at:number}
const props=defineProps<{target:Alias|null}>(),emit=defineEmits<{close:[];deleted:[]}>(),ui=useUI(),data=useData();
const preview=ref<DeletePreview|null>(null),confirmation=ref(''),busy=ref(false),error=ref(''),done=ref('');
/** 功能：读取一次性删除预览，不删除数据；参数：无；返回值：异步完成。 */
async function load(){if(!props.target||busy.value)return;if(!ui.authorized){ui.authOpen=true;return;}busy.value=true;preview.value=null;error.value='';confirmation.value='';try{preview.value=await api.mutate<DeletePreview>(`/api/account/${encodeURIComponent(props.target.account_id)}/delete-preview`,{});}catch(e){error.value=e instanceof Error?e.message:'预览失败';}finally{busy.value=false;}}
watch(()=>props.target,value=>{preview.value=null;confirmation.value='';error.value='';done.value='';if(value)void load();});
watch(()=>ui.authorized,value=>{if(!value){preview.value=null;confirmation.value='';}});
/** 功能：执行已授权且输入账号ID确认的删除，不自动重试；参数：无；返回值：实际结果，刷新失败不会误报删除失败。 */
async function remove(){if(!props.target||!preview.value||confirmation.value!==props.target.account_id||busy.value)return;if(!ui.authorized){ui.authOpen=true;return;}const id=props.target.account_id,token=preview.value.delete_token;preview.value=null;busy.value=true;error.value='';try{const r=await api.mutate<{deleted_reports:number;deleted_rows:number}>(`/api/account/${encodeURIComponent(id)}/delete`,{delete_token:token,confirmation:confirmation.value});done.value=`已删除 ${r.deleted_reports} 份报告、${r.deleted_rows} 条窗口记录，设备及令牌保留。`;confirmation.value='';await data.refresh();emit('deleted');}catch(e){error.value=e instanceof Error?e.message:'结果未确认，请刷新核实后再操作';}finally{busy.value=false;}}
/** 功能：避免请求处理中关闭对话框；参数：done为关闭回调；返回值：无。 */
function close(doneCallback?:()=>void){if(busy.value)return;emit('close');doneCallback?.();}
</script>
<template><el-dialog :model-value="Boolean(target)" title="永久删除账号记录" width="min(540px,94vw)" :before-close="close" :close-on-click-modal="false" :close-on-press-escape="!busy"><p><strong>{{target?.display_name||target?.account_id}}</strong></p><p class="mono">{{target?.account_id}}</p><el-alert title="删除该账号全部额度历史、名称映射和隐藏标记，无法撤销。设备及设备令牌保留；之后重新使用仍可能出现。" type="warning" :closable="false"/><p>在线使用中的账号禁止删除。预览有效5分钟，执行前再次检查。</p><el-button v-if="!done" :loading="busy" @click="load">{{ui.authorized?'重新读取删除预览':'管理员授权'}}</el-button><template v-if="preview"><el-descriptions :column="2" border style="margin:16px 0"><el-descriptions-item label="报告">{{preview.report_count}}</el-descriptions-item><el-descriptions-item label="窗口记录">{{preview.snapshot_rows}}</el-descriptions-item><el-descriptions-item label="涉及设备">{{preview.device_count}}</el-descriptions-item><el-descriptions-item label="有效至">{{date(preview.expires_at)}}</el-descriptions-item></el-descriptions><p>请输入完整账号 ID 确认：</p><el-input v-model="confirmation" :disabled="busy" aria-label="输入完整账号ID确认删除" autocomplete="off"/></template><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-alert v-if="done" :title="done" type="success" :closable="false"/><template #footer><el-button :disabled="busy" @click="close()">{{done?'完成':'取消'}}</el-button><el-button v-if="!done" type="danger" :loading="busy" :disabled="!preview||confirmation!==target?.account_id||!ui.authorized" @click="remove">确认永久删除账号记录</el-button></template></el-dialog></template>
